		printUsage()
		os.Exit(0)
	}

	if flagNoColor {
		colorReset = ""
		colorRed = ""
		colorGreen = ""
		colorYellow = ""
		colorCyan = ""
		colorGray = ""
	}

	var input io.Reader
	var followOut io.Writer

	if flagFile != "" {
		file, err := os.Open(flagFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
			os.Exit(1)
		}
		defer file.Close()
		input = file
	} else {
		input = os.Stdin
	}

	if flagFollowOutput != "" {
		file, err := os.Create(flagFollowOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error creating follow-output file: %v\n", err)
			os.Exit(1)
		}
		defer file.Close()
		followOut = file
	} else if flagFollow {
		followOut = os.Stdout
	}

	// Parse all events
	packages := make(map[string]*PackageStats)
	scanner := bufio.NewScanner(input)

	for scanner.Scan() {
		line := scanner.Bytes()
		var event TestEvent
		if err := json.Unmarshal(line, &event); err != nil {
			continue
		}

		if followOut != nil {
			if flagIncludeTime {
				fmt.Fprintf(followOut, "[%s] %s\n", event.Time, line)
			} else {
				fmt.Fprintf(followOut, "%s\n", line)
			}
		}

		pkg := event.Package
		if pkg == "" {
			continue
		}

		if _, ok := packages[pkg]; !ok {
			packages[pkg] = &PackageStats{
				Package: pkg,
				Results: []TestResult{},
			}
		}

		stats := packages[pkg]

		switch event.Action {
		case "pass":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "pass",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
				stats.Pass++
			}
		case "fail":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "fail",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
				stats.Fail++
			} else {
				// Package-level failure
				stats.Fail++
				result := TestResult{
					Test:    "",
					Package: pkg,
					Status:  "fail",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
			}
		case "skip":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "skip",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
				stats.Skip++
			}
		case "output":
			if event.Test != "" {
				// Find the test result and add output
				for i := range stats.Results {
					if stats.Results[i].Test == event.Test {
						stats.Results[i].Output = append(stats.Results[i].Output, event.Output)
						break
					}
				}
			}
		}
	}

	// Calculate package-level status
	for _, stats := range packages {
		if stats.Fail > 0 {
			stats.Status = "fail"
		} else if stats.Skip > 0 {
			stats.Status = "skip"
		} else {
			stats.Status = "pass"
		}
	}

	// Determine if we should display failures
	displayFailed := true
	displayPassed := flagAll || flagPass
	displaySkipped := flagAll || flagSkip

	// Collect all results to display
	resultsToDisplay := []TestResult{}
	failedPackages := []*PackageStats{}

	for _, stats := range packages {
		if stats.Status == "fail" {
			failedPackages = append(failedPackages, stats)
		}
	}

	// Sort failed packages
	sort.Slice(failedPackages, func(i, j int) bool {
		return failedPackages[i].Package < failedPackages[j].Package
	})

	// Collect test results to display
	for _, stats := range packages {
		for _, result := range stats.Results {
			if result.Status == "fail" && displayFailed {
				resultsToDisplay = append(resultsToDisplay, result)
			} else if result.Status == "pass" && displayPassed {
				resultsToDisplay = append(resultsToDisplay, result)
			} else if result.Status == "skip" && displaySkipped {
				resultsToDisplay = append(resultsToDisplay, result)
			}
		}
	}

	// Display test results table
	if len(resultsToDisplay) > 0 {
		displayResultsTable(resultsToDisplay)
	}

	// Display failures with output
	if displayFailed && len(failedPackages) > 0 {
		displayFailures(failedPackages, packages)
	}

	// Display package summary table
	displayPackageSummary(packages, failedPackages)

	// Return appropriate exit code
	hasFailures := false
	for _, stats := range packages {
		if stats.Status == "fail" {
			hasFailures = true
			break
		}
	}
	if hasFailures {
		os.Exit(1)
	}
}

func displayResultsTable(results []TestResult) {
	if len(results) == 0 {
		return
	}

	// Sort results
	sort.Slice(results, func(i, j int) bool {
		if results[i].Status != results[j].Status {
			statusOrder := map[string]int{"fail": 0, "pass": 1, "skip": 2}
			return statusOrder[results[i].Status] < statusOrder[results[j].Status]
		}
		return results[i].Test < results[j].Test
	})

	// Calculate column widths
	statusWidth := len("Status")
	elapsedWidth := len("Elapsed")
	testWidth := len("Test")
	packageWidth := len("Package")

	for _, r := range results {
		if len(statusStr(r.Status)) > statusWidth {
			statusWidth = len(statusStr(r.Status))
		}
		if len(fmt.Sprintf("%.2f", r.Elapsed)) > elapsedWidth {
			elapsedWidth = len(fmt.Sprintf("%.2f", r.Elapsed))
		}
		if len(r.Test) > testWidth {
			testWidth = len(r.Test)
		}
		if len(r.Package) > packageWidth {
			packageWidth = len(r.Package)
		}
	}

	// Print header
	fmt.Print("╭")
	fmt.Print(strings.Repeat("─", statusWidth+2))
	fmt.Print("┬")
	fmt.Print(strings.Repeat("─", elapsedWidth+2))
	fmt.Print("┬")
	fmt.Print(strings.Repeat("─", testWidth+2))
	fmt.Print("┬")
	fmt.Print(strings.Repeat("─", packageWidth+2))
	fmt.Println("╮")

	fmt.Print("│ ")
	fmt.Print(padRight("Status", statusWidth))
	fmt.Print(" │ ")
	fmt.Print(padRight("Elapsed", elapsedWidth))
	fmt.Print(" │ ")
	fmt.Print(padRight("Test", testWidth))
	fmt.Print(" │ ")
	fmt.Print(padRight("Package", packageWidth))
	fmt.Println(" │")

	fmt.Print("├")
	fmt.Print(strings.Repeat("─", statusWidth+2))
	fmt.Print("┼")
	fmt.Print(strings.Repeat("─", elapsedWidth+2))
	fmt.Print("┼")
	fmt.Print(strings.Repeat("─", testWidth+2))
	fmt.Print("┼")
	fmt.Print(strings.Repeat("─", packageWidth+2))
	fmt.Println("┤")

	// Print rows
	for _, r := range results {
		fmt.Print("│ ")
		fmt.Print(colorizeStatus(r.Status, padRight(statusStr(r.Status), statusWidth)))
		fmt.Print(" │ ")
		fmt.Print(padRight(fmt.Sprintf("%.2f", r.Elapsed), elapsedWidth))
		fmt.Print(" │ ")
		fmt.Print(padRight(r.Test, testWidth))
		fmt.Print(" │ ")
		fmt.Print(padRight(r.Package, packageWidth))
		fmt.Println(" │")
	}

	fmt.Print("╰")
	fmt.Print(strings.Repeat("─", statusWidth+2))
	fmt.Print("┴")
	fmt.Print(strings.Repeat("─", elapsedWidth+2))
	fmt.Print("┴")
	fmt.Print(strings.Repeat("─", testWidth+2))
	fmt.Print("┴")
	fmt.Print(strings.Repeat("─", packageWidth+2))
	fmt.Println("╯")
}

func displayFailures(failedPackages []*PackageStats, packages map[string]*PackageStats) {
	for _, stats := range failedPackages {
		// Find failing tests
		failingTests := []TestResult{}
		for _, result := range stats.Results {
			if result.Status == "fail" {
				failingTests = append(failingTests, result)
			}
		}

		if len(failingTests) > 0 {
			// Print package header
			fmt.Printf("%s┏", colorGray)
			fmt.Print(strings.Repeat("━", len(fmt.Sprintf("FAIL  package: %s", stats.Package))+4))
			fmt.Printf("┓%s\n", colorReset)

			fmt.Printf("%s┃%s   %sFAIL%s  package: %s   %s┃%s\n", 
				colorGray, colorReset, colorRed, colorReset, stats.Package, colorGray, colorReset)

			fmt.Printf("%s┗", colorGray)
			fmt.Print(strings.Repeat("━", len(fmt.Sprintf("FAIL  package: %s", stats.Package))+4))
			fmt.Printf("┛%s\n", colorReset)
			fmt.Println()

			// Print failures with output
			for _, result := range failingTests {
				if len(result.Output) > 0 {
					// Parse output to extract the relevant failure info
					output := strings.Join(result.Output, "")
					// Print lines related to the failure
					for _, line := range strings.Split(output, "\n") {
						if strings.Contains(line, "FAIL") || strings.Contains(line, "---") {
							fmt.Println(line)
						} else if strings.TrimSpace(line) != "" && strings.Contains(line, ":") {
							fmt.Println(line)
						}
					}
				}
			}

			// Print separator
			fmt.Println(strings.Repeat("─", 100))
			fmt.Println()
		}
	}
}

