func statusStr(status string) string {
	switch status {
	case "pass":
		return "PASS"
	case "fail":
		return "FAIL"
	case "skip":
		return "SKIP"
	default:
		return ""
	}
}

func colorizeStatus(status, text string) string {
	switch status {
	case "pass":
		return colorGreen + text + colorReset
	case "fail":
		return colorRed + text + colorReset
	case "skip":
		return colorYellow + text + colorReset
	default:
		return text
	}
}

func padRight(s string, width int) string {
	if len(s) >= width {
		return s
	}
	return s + strings.Repeat(" ", width-len(s))
}

func formatElapsed(seconds float64) string {
	if seconds < 1 {
		return fmt.Sprintf("%.2fs", seconds)
	}
	d := time.Duration(int64(seconds*1000)) * time.Millisecond
	return fmt.Sprintf("%.2fs", d.Seconds())
}

func printUsage() {
	fmt.Println(`Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
