			packages[pkg] = &PackageStats{
				Package: pkg,
				Results: []TestResult{},
			}
		}

		stats := packages[pkg]

		switch event.Action {
		case "pass":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "pass",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
				stats.Pass++
			}
		case "fail":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "fail",
					Elapsed: event.Elapsed,
				}
