func statusStr(status string) string {
	switch status {
	case "pass":
		return "PASS"
	case "fail":
		return "FAIL"
	case "skip":
		return "SKIP"
	default:
		return ""
	}
}

func colorizeStatus(status, text string) string {
	switch status {
	case "pass":
		return colorGreen + text + colorReset
	case "fail":
		return colorRed + text + colorReset
	case "skip":
		return colorYellow + text + colorReset
	default:
