				Package: pkg,
				Results: []TestResult{},
			}
		}

		stats := packages[pkg]

		switch event.Action {
		case "pass":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "pass",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
				stats.Pass++
			}
		case "fail":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "fail",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
				stats.Fail++
			} else {
				// Package-level failure
				stats.Fail++
				result := TestResult{
					Test:    "",
					Package: pkg,
					Status:  "fail",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
			}
		case "skip":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "skip",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
				stats.Skip++
			}
		case "output":
			if event.Test != "" {
				// Find the test result and add output
				found := false
				for i := range stats.Results {
					if stats.Results[i].Test == event.Test && stats.Results[i].Status == "fail" {
						stats.Results[i].Output = append(stats.Results[i].Output, event.Output)
						found = true
						break
					}
				}
				// If not found yet, we may need to create a temporary one
				if !found {
					for i := range stats.Results {
						if stats.Results[i].Test == event.Test {
							stats.Results[i].Output = append(stats.Results[i].Output, event.Output)
							break
						}
					}
				}
			}
		}
