func main() {
	flag.Parse()

	// Check for NO_COLOR environment variable
	if os.Getenv("NO_COLOR") != "" {
		flagNoColor = true
	}

	if flagVersion {
		fmt.Printf("tparse version: %s\n", version)
		os.Exit(0)
	}

	if flagHelp {
		printUsage()
		os.Exit(0)
	}

	if flagNoColor {
		colorReset = ""
		colorRed = ""
		colorGreen = ""
		colorYellow = ""
		colorCyan = ""
		colorGray = ""
	}

	var input io.Reader
	var followOut io.Writer

	if flagFile != "" {
		file, err := os.Open(flagFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
			os.Exit(1)
		}
		defer file.Close()
		input = file
	} else {
		input = os.Stdin
	}

	if flagFollowOutput != "" {
		file, err := os.Create(flagFollowOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error creating follow-output file: %v\n", err)
			os.Exit(1)
		}
		defer file.Close()
		followOut = file
	} else if flagFollow {
		followOut = os.Stdout
	}

	// Parse all events
	packages := make(map[string]*PackageStats)
	scanner := bufio.NewScanner(input)

	for scanner.Scan() {
		line := scanner.Bytes()
		var event TestEvent
		if err := json.Unmarshal(line, &event); err != nil {
			continue
		}

		if followOut != nil {
			if flagIncludeTime {
				fmt.Fprintf(followOut, "[%s] %s\n", event.Time, line)
			} else {
