			packages[pkg] = &PackageStats{
				Package:       pkg,
				Results:       []TestResult{},
				TestOutputMap: make(map[string][]string),
			}
		}

		stats := packages[pkg]

		switch event.Action {
		case "pass":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "pass",
					Elapsed: event.Elapsed,
				}
				// Add any captured output
				if outputs, ok := stats.TestOutputMap[event.Test]; ok {
					result.Output = outputs
				}
				stats.Results = append(stats.Results, result)
				stats.Pass++
			}
		case "fail":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "fail",
					Elapsed: event.Elapsed,
				}
				// Add any captured output
				if outputs, ok := stats.TestOutputMap[event.Test]; ok {
					result.Output = outputs
				}
				stats.Results = append(stats.Results, result)
				stats.Fail++
			} else {
				// Package-level failure
				stats.Fail++
				result := TestResult{
					Test:    "",
					Package: pkg,
					Status:  "fail",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
			}
		case "skip":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "skip",
					Elapsed: event.Elapsed,
				}
				// Add any captured output
				if outputs, ok := stats.TestOutputMap[event.Test]; ok {
					result.Output = outputs
				}
				stats.Results = append(stats.Results, result)
				stats.Skip++
			}
		case "output":
			if event.Test != "" {
				// Store output for this test
				stats.TestOutputMap[event.Test] = append(stats.TestOutputMap[event.Test], event.Output)
			}
		}
	}

	// Calculate package-level status
	for _, stats := range packages {
		if stats.Fail > 0 {
			stats.Status = "fail"
		} else if stats.Skip > 0 {
			stats.Status = "skip"
		} else {
			stats.Status = "pass"
		}
