func main() {
	flag.Parse()

	// Check for NO_COLOR environment variable
	if os.Getenv("NO_COLOR") != "" {
		flagNoColor = true
	}

	if flagVersion {
		fmt.Printf("tparse version: %s\n", version)
		os.Exit(0)
	}

	if flagHelp {
		printUsage()
		os.Exit(0)
	}

	if flagNoColor {
		colorReset = ""
		colorRed = ""
		colorGreen = ""
		colorYellow = ""
		colorCyan = ""
		colorGray = ""
	}

	var input io.Reader
	var followOut io.Writer

	if flagFile != "" {
		file, err := os.Open(flagFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
			os.Exit(1)
		}
		defer file.Close()
		input = file
	} else {
