cat << 'EOF' > /workspace/main.go
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
	"time"
)

const version = "(devel)"

type TestEvent struct {
	Time    string `json:"Time"`
	Action  string `json:"Action"`
	Package string `json:"Package"`
	Test    string `json:"Test"`
	Elapsed float64 `json:"Elapsed"`
	Output  string `json:"Output"`
}

type TestResult struct {
	Test       string
	Package    string
	Status     string // pass, fail, skip
	Elapsed    float64
	Output     []string
}

type PackageStats struct {
	Package        string
	Pass           int
	Fail           int
	Skip           int
	Elapsed        float64
	Cover          string
	Results        []TestResult
	Status         string // pass, fail, skip
	TestOutputMap  map[string][]string // test name -> output lines
}

var (
	flagAll             bool
	flagPass            bool
	flagSkip            bool
	flagNoColor         bool
	flagSmallScreen     bool
	flagSlow            int
	flagSort            string
	flagFormat          string
	flagFile            string
	flagFollow          bool
	flagFollowOutput    string
	flagIncludeTime     bool
	flagProgress        bool
	flagCompare         string
	flagTrimPath        string
	flagNotests         bool
	flagHelp            bool
	flagVersion         bool
)

var (
	colorReset  = "\033[0m"
	colorRed    = "\033[91m"
	colorGreen  = "\033[92m"
	colorYellow = "\033[93m"
	colorCyan   = "\033[96m"
	colorGray   = "\033[38;5;103m"
)

func init() {
	flag.BoolVar(&flagAll, "all", false, "Display table event for pass and skip. (Failed items always displayed)")
	flag.BoolVar(&flagPass, "pass", false, "Display table for passed tests.")
	flag.BoolVar(&flagSkip, "skip", false, "Display table for skipped tests.")
	flag.BoolVar(&flagNoColor, "nocolor", false, "Disable all colors. (NO_COLOR also supported)")
	flag.BoolVar(&flagSmallScreen, "smallscreen", false, "Split subtest names vertically to fit on smaller screens.")
	flag.IntVar(&flagSlow, "slow", 0, "Number of slowest tests to display. Default is 0, display all.")
	flag.StringVar(&flagSort, "sort", "name", "Sort table output by attribute [name, elapsed, cover]. Default is name.")
	flag.StringVar(&flagFormat, "format", "basic", "The output format for tables [basic, plain, markdown]. Default is basic.")
	flag.StringVar(&flagFile, "file", "", "Read test output from a file.")
	flag.BoolVar(&flagFollow, "follow", false, "Follow raw output from go test to stdout.")
	flag.StringVar(&flagFollowOutput, "follow-output", "", "Write raw output from go test to a file (takes precedence over -follow).")
	flag.BoolVar(&flagIncludeTime, "include-timestamp", false, "Include timestamps in follow output.")
	flag.BoolVar(&flagProgress, "progress", false, "Print a single summary line for each package. Useful for long running test suites.")
	flag.StringVar(&flagCompare, "compare", "", "Compare against a previous test output file. (experimental)")
	flag.StringVar(&flagTrimPath, "trimpath", "", "Remove path prefix from package names in output, simplifying their display.")
	flag.BoolVar(&flagNotests, "notests", false, "Display packages containing no test files or empty test files.")
	flag.BoolVar(&flagHelp, "h", false, "Show help.")
	flag.BoolVar(&flagVersion, "v", false, "Show version.")
}

func main() {
	flag.Parse()

	// Check for NO_COLOR environment variable
	if os.Getenv("NO_COLOR") != "" {
		flagNoColor = true
	}

	if flagVersion {
		fmt.Printf("tparse version: %s\n", version)
		os.Exit(0)
	}

	if flagHelp {
		printUsage()
		os.Exit(0)
	}

	if flagNoColor {
		colorReset = ""
		colorRed = ""
		colorGreen = ""
		colorYellow = ""
		colorCyan = ""
		colorGray = ""
	}

	var input io.Reader
	var followOut io.Writer

	if flagFile != "" {
		file, err := os.Open(flagFile)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error opening file: %v\n", err)
			os.Exit(1)
		}
		defer file.Close()
		input = file
	} else {
		input = os.Stdin
	}

	if flagFollowOutput != "" {
		file, err := os.Create(flagFollowOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error creating follow-output file: %v\n", err)
			os.Exit(1)
		}
		defer file.Close()
		followOut = file
	} else if flagFollow {
		followOut = os.Stdout
	}

	// Parse all events
	packages := make(map[string]*PackageStats)
	scanner := bufio.NewScanner(input)

	for scanner.Scan() {
		line := scanner.Bytes()
		var event TestEvent
		if err := json.Unmarshal(line, &event); err != nil {
			continue
		}

		if followOut != nil {
			if flagIncludeTime {
				fmt.Fprintf(followOut, "[%s] %s\n", event.Time, line)
			} else {
				fmt.Fprintf(followOut, "%s\n", line)
			}
		}

		pkg := event.Package
		if pkg == "" {
			continue
		}

		if _, ok := packages[pkg]; !ok {
			packages[pkg] = &PackageStats{
				Package:       pkg,
				Results:       []TestResult{},
				TestOutputMap: make(map[string][]string),
			}
		}

		stats := packages[pkg]

		switch event.Action {
		case "pass":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "pass",
					Elapsed: event.Elapsed,
				}
				// Add any captured output
				if outputs, ok := stats.TestOutputMap[event.Test]; ok {
					result.Output = outputs
				}
				stats.Results = append(stats.Results, result)
				stats.Pass++
			}
		case "fail":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "fail",
					Elapsed: event.Elapsed,
				}
				// Add any captured output
				if outputs, ok := stats.TestOutputMap[event.Test]; ok {
					result.Output = outputs
				}
				stats.Results = append(stats.Results, result)
				stats.Fail++
			} else {
				// Package-level failure
				stats.Fail++
				result := TestResult{
					Test:    "",
					Package: pkg,
					Status:  "fail",
					Elapsed: event.Elapsed,
				}
				stats.Results = append(stats.Results, result)
			}
		case "skip":
			if event.Test != "" {
				result := TestResult{
					Test:    event.Test,
					Package: pkg,
					Status:  "skip",
					Elapsed: event.Elapsed,
				}
				// Add any captured output
				if outputs, ok := stats.TestOutputMap[event.Test]; ok {
					result.Output = outputs
				}
				stats.Results = append(stats.Results, result)
				stats.Skip++
			}
		case "output":
			if event.Test != "" {
				// Store output for this test
				stats.TestOutputMap[event.Test] = append(stats.TestOutputMap[event.Test], event.Output)
			}
		}
	}

	// Calculate package-level status
	for _, stats := range packages {
		if stats.Fail > 0 {
			stats.Status = "fail"
		} else if stats.Skip > 0 {
			stats.Status = "skip"
		} else {
			stats.Status = "pass"
		}
	}

	// Determine if we should display failures
	displayFailed := true
	displayPassed := flagAll || flagPass
	displaySkipped := flagAll || flagSkip

	// Collect all results to display
	resultsToDisplay := []TestResult{}
	failedPackages := []*PackageStats{}

	for _, stats := range packages {
		if stats.Status == "fail" {
			failedPackages = append(failedPackages, stats)
		}
	}

	// Sort failed packages
	sort.Slice(failedPackages, func(i, j int) bool {
		return failedPackages[i].Package < failedPackages[j].Package
	})

	// Collect test results to display
	for _, stats := range packages {
		for _, result := range stats.Results {
			if result.Status == "fail" && displayFailed {
				resultsToDisplay = append(resultsToDisplay, result)
			} else if result.Status == "pass" && displayPassed {
				resultsToDisplay = append(resultsToDisplay, result)
			} else if result.Status == "skip" && displaySkipped {
				resultsToDisplay = append(resultsToDisplay, result)
			}
		}
	}

	// Display test results table
	if len(resultsToDisplay) > 0 {
		displayResultsTable(resultsToDisplay, flagFormat)
	}

	// Display failures with output
	if displayFailed && len(failedPackages) > 0 {
		displayFailures(failedPackages, packages)
	}

	// Display package summary table
	displayPackageSummary(packages, failedPackages, flagFormat)

	// Return appropriate exit code
	hasFailures := false
	for _, stats := range packages {
		if stats.Status == "fail" {
			hasFailures = true
			break
		}
	}
	if hasFailures {
		os.Exit(1)
	}
}

func displayResultsTable(results []TestResult, format string) {
	if len(results) == 0 {
		return
	}

	// Sort results
	sort.Slice(results, func(i, j int) bool {
		if results[i].Status != results[j].Status {
			statusOrder := map[string]int{"fail": 0, "pass": 1, "skip": 2}
			return statusOrder[results[i].Status] < statusOrder[results[j].Status]
		}
		return results[i].Test < results[j].Test
	})

	// Calculate column widths
	statusWidth := len("Status")
	elapsedWidth := len("Elapsed")
	testWidth := len("Test")
	packageWidth := len("Package")

	for _, r := range results {
		if len(statusStr(r.Status)) > statusWidth {
			statusWidth = len(statusStr(r.Status))
		}
		if len(fmt.Sprintf("%.2f", r.Elapsed)) > elapsedWidth {
			elapsedWidth = len(fmt.Sprintf("%.2f", r.Elapsed))
		}
		if len(r.Test) > testWidth {
			testWidth = len(r.Test)
		}
		if len(r.Package) > packageWidth {
			packageWidth = len(r.Package)
		}
	}

	if format == "plain" {
		displayPlainTable(results, statusWidth, elapsedWidth, testWidth, packageWidth)
	} else if format == "markdown" {
		displayMarkdownTable(results, statusWidth, elapsedWidth, testWidth, packageWidth)
	} else {
		displayBasicTable(results, statusWidth, elapsedWidth, testWidth, packageWidth)
	}
}

func displayBasicTable(results []TestResult, statusWidth, elapsedWidth, testWidth, packageWidth int) {
	// Print header
	fmt.Print("╭")
